<?php
declare(strict_types=1);
use DigiForge\POD\PrintifyAcceptanceSafetyGeneration as Generation;
final class PrintifyAcceptanceSafetyGenerationTest extends WP_UnitTestCase {
 private array $settings=[];
 public function set_up():void {parent::set_up();global $wpdb;$wpdb->query('COMMIT');$wpdb->query('SET autocommit=1');$this->settings=$wpdb->get_results('SELECT * FROM '.\DigiForge\Database\Tables::settings(),ARRAY_A);\DigiForge\Core\Settings::protectProduction();$wpdb->delete($wpdb->options,['option_name'=>'df_acceptance_safety_generation_v1']);}
 public function tear_down():void {global $wpdb;\DigiForge\Security\Logger::write('printify_acceptance_generation_fixture_cleanup');$wpdb->delete($wpdb->options,['option_name'=>'df_acceptance_safety_generation_v1']);$wpdb->query('DELETE FROM '.\DigiForge\Database\Tables::settings());foreach($this->settings as $row)$wpdb->insert(\DigiForge\Database\Tables::settings(),$row);parent::tear_down();}
 private function next():string {self::assertTrue(class_exists(Generation::class),'Durable acceptance revocation generation required');$r=Generation::terminate();self::assertNotWPError($r);return $r;}
 public function testMissingGenerationDeniesWithoutCreatingState():void {self::assertTrue(class_exists(Generation::class));self::assertWPError(Generation::current());self::assertFalse(get_option('df_acceptance_safety_generation_v1',false));}
 public function testEveryTerminationChangesGenerationAndRejectsStaleSession():void {$a=$this->next();self::assertTrue(Generation::check($a)===true);$b=$this->next();self::assertNotSame($a,$b);self::assertWPError(Generation::check($a));self::assertTrue(Generation::check($b)===true);}
 public function testRepeatedExplicitEmergencyEventRotatesWhileStopAllIsTrue():void {$a=$this->next();self::assertTrue(\DigiForge\Core\Settings::get('stop_all',true));$b=$this->next();self::assertWPError(Generation::check($a));$this->next();self::assertWPError(Generation::check($b));}
 public function testTamperedStateFailsClosed():void {$a=$this->next();global $wpdb;$wpdb->update($wpdb->options,['option_value'=>'{}'],['option_name'=>'df_acceptance_safety_generation_v1']);self::assertWPError(Generation::check($a));}
 public function testMissingAuditAnchorDenies():void {$a=$this->next();global $wpdb;$wpdb->delete(\DigiForge\Database\Tables::audit_log(),['event_type'=>'printify_acceptance_emergency_generation','object_id'=>$a]);self::assertWPError(Generation::check($a));}
 public function testOuterTransactionTerminationIsRejectedNotAcknowledged():void {$a=$this->next();global $wpdb;$wpdb->query('START TRANSACTION');try{self::assertWPError(Generation::terminate());self::assertWPError(Generation::check($a));}finally{$wpdb->query('ROLLBACK');}self::assertTrue(Generation::check($a)===true,'Known blocked requirement: rejected event cannot durably invalidate outside caller transaction');}
 public function testExplicitEmergencyEventCannotEnableBusinessOperations():void {$a=$this->next();$this->next();self::assertWPError(Generation::check($a));self::assertFalse(\DigiForge\Core\Settings::is_enabled('printify'));self::assertTrue(\DigiForge\Core\Settings::safety_locked());}
 public function testRejectedTerminationNeverCommitsCallerTransaction():void {$this->next();global $wpdb;$wpdb->query('START TRANSACTION');try{self::assertWPError(Generation::terminate());self::assertSame('1',(string)$wpdb->get_var('SELECT @@session.in_transaction'));}finally{$wpdb->query('ROLLBACK');}}
 public function testConcurrentCompareExchangeLoserCannotOverwriteNewEvent():void {
  $old=$this->next();global $wpdb;$primary=$wpdb;$secondary=new wpdb(DB_USER,DB_PASSWORD,DB_NAME,DB_HOST);$secondary->set_prefix($primary->prefix);$winner=null;$entered=false;$filter=static function(string $sql)use(&$entered,&$winner,$primary,$secondary):string{if(!$entered&&str_starts_with($sql,'UPDATE '.$primary->options.' SET option_value=')&&str_contains($sql,'df_acceptance_safety_generation_v1')){$entered=true;$GLOBALS['wpdb']=$secondary;try{$winner=Generation::terminate();}finally{$GLOBALS['wpdb']=$primary;}}return $sql;};add_filter('query',$filter);try{$loser=Generation::terminate();}finally{remove_filter('query',$filter);$secondary->close();}self::assertNotWPError($winner);self::assertWPError($loser);self::assertSame($winner,Generation::current());self::assertWPError(Generation::check($old));
 }
 public function testAuditFailureAfterGenerationChangeDeniesOldAndNewEvidence():void {
  $old=$this->next();$table=\DigiForge\Database\Tables::audit_log();$filter=static fn(string $sql):string=>str_starts_with($sql,'INSERT INTO `'.$table.'`')&&str_contains($sql,'printify_acceptance_emergency_generation')?'INSERT INTO nonexistent_acceptance_audit_table VALUES (1)':$sql;add_filter('query',$filter);global $wpdb;$previous=$wpdb->suppress_errors(true);try{self::assertWPError(Generation::terminate());}finally{remove_filter('query',$filter);$wpdb->suppress_errors($previous);}self::assertWPError(Generation::check($old));self::assertWPError(Generation::current());
 }
}
